# Generated by Phase: IMPLEMENT | Feature: #115
"""Checklist vocabulary — the one definition of a done item (#115).

A task item `- [c] …` (any indent; bullet `-`, `*`, `+`, or `1.` / `1)` with a mark ` `, `x`, `X`, `!`) is done only when `c` is `x` or `X`. `[ ]` is open, `[!]` failed
(QA's `- [!] FAILED`), any other mark is not done. Readers: the completion hook
(check-completion-gate.sh) and QA's auto-approval count (Factory-qa-verify) — none re-derives.
"""
from __future__ import annotations

import re

ITEM = re.compile(r"^\s*(?:[-*+]\s+\[(.)\]|\d+[.)]\s+\[([ xX!])\])")   # `3. [B] option` is prose, not a task
DONE = frozenset("xX")


def count(text: str) -> dict:
    c = {"done": 0, "open": 0, "failed": 0, "other": 0}
    for line in text.splitlines():
        m = ITEM.match(line)
        if m:
            mark = m.group(1) or m.group(2)
            c["done" if mark in DONE else "open" if mark == " " else "failed" if mark == "!" else "other"] += 1
    c["total"] = sum(c.values())
    c["not_done"] = c["total"] - c["done"]
    return c


def render(c: dict) -> str:
    return (f"checklist: {c['done']} done · {c['open']} open [ ] · {c['failed']} failed [!] · {c['other']} other mark "
            f"(total {c['total']}) — only [x] is done")
